package com.smartresponse.domain; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="shelters") public class Shelter {@Id @GeneratedValue private UUID id;private String name;private String addressLine;private double latitude;private double longitude;private int capacityTotal;private int capacityAvailable;private String status="OPEN";private Instant createdAt=Instant.now();private Instant updatedAt=Instant.now();@Version private long version;protected Shelter(){}public Shelter(String n,String a,double lat,double lon,int c){name=n;addressLine=a;latitude=lat;longitude=lon;capacityTotal=c;capacityAvailable=c;}public UUID getId(){return id;}public String getName(){return name;}public String getAddressLine(){return addressLine;}public int getCapacityAvailable(){return capacityAvailable;}public String getStatus(){return status;}public void setCapacity(int capacity){if(capacity<0||capacity>capacityTotal)throw new IllegalArgumentException("Invalid available capacity");capacityAvailable=capacity;updatedAt=Instant.now();}}
